#define BLUR 4

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    int blur = BLUR;

    vec2 base = fragCoord.xy - float(blur);
    vec2 oneOverRes = 1. / iResolution.xy;

    vec4 total = vec4(0.);
    int counter = 0;
    for (int x = -blur; x <= blur; x += 1) {
        for (int y = -blur; y <= blur; y += 1) {
            total += texture(iChannel0, (base.xy + vec2(x, y)) * oneOverRes.xy);
            counter += 1;
        }
    }

    fragColor = total / float(counter);
}
